import { describe, expect, it } from 'vitest';

import { PUB_ROUTES } from './pub.routes';

/**
 * Smoke spec for @cordele/pub.
 *
 * Generated by fe-nx-register-module.py. It guards the module contract the
 * shell relies on: the route table exists, every route declares a path, and
 * each one lazily loads a component or redirects.
 */
describe('@cordele/pub route contract', () => {
  it('exposes at least one route', () => {
    expect(Array.isArray(PUB_ROUTES)).toBe(true);
    expect(PUB_ROUTES.length).toBeGreaterThan(0);
  });

  it('every route declares a path', () => {
    for (const route of PUB_ROUTES) {
      expect(typeof route.path).toBe('string');
    }
  });

  it('every route lazily loads a component or redirects', () => {
    for (const route of PUB_ROUTES) {
      const lazy =
        typeof route.loadComponent === 'function' ||
        typeof route.loadChildren === 'function' ||
        typeof route.redirectTo === 'string';
      expect(lazy).toBe(true);
    }
  });

  it('has no duplicate paths', () => {
    const paths = PUB_ROUTES.map((r) => r.path);
    expect(new Set(paths).size).toBe(paths.length);
  });
});
